import { expect, it } from "vitest";

import type { HumanInterventionRequest } from "../../src/shared/intervention";
import { interventionFileDocument, parseInterventionFile } from "../../src/shared/intervention-file";

it("round-trips a representative non-empty interventions array", () => {
  const interventions: HumanInterventionRequest[] = [
    {
      id: "intervention-1",
      taskId: "task-1",
      kind: "AUTHORIZATION",
      question: "Approve the deployment to production?",
      blockingStepId: "step-deploy",
      contextSummary: "The plan reached its release step and needs a human decision.",
      createdAt: "2026-01-01T00:00:00.000Z",
    },
    {
      id: "intervention-2",
      taskId: "task-2",
      kind: "CAPTCHA",
      question: "Solve the challenge to continue the crawl?",
      blockingStepId: "step-crawl",
      contextSummary: "The target site presented a challenge the run cannot answer.",
      createdAt: "2026-01-02T00:00:00.000Z",
    },
  ];

  const document = interventionFileDocument(interventions);
  const parsed = parseInterventionFile(JSON.stringify(document));

  expect(parsed.status).toBe("ok");
  if (parsed.status !== "ok") {
    throw new Error(`expected an ok parse result, got ${parsed.status}`);
  }

  // The round-trip itself: any implementation that drops, reorders or mangles an entry refutes this.
  expect(parsed.interventions).toEqual(interventions);
  // And the values survive by identity, so a parser that returned the right COUNT of blank entries
  // would still fail.
  expect(parsed.interventions.map((entry) => entry.id)).toEqual(["intervention-1", "intervention-2"]);
});
